/* [판독결과 검토] 담당자 지정 권한 - countAssignAuthority */ SELECT COUNT(*) FROM ocuoc_useri_m U WHERE U.EMPNO = #{userId} AND (
U.HRA_PSTN_CD IN #{code}
1 = 0
OR EXISTS (SELECT 1 FROM ocuoc_usrol_r R WHERE R.USER_ID = U.EMPNO AND NVL(R.USE_YN, 'Y') = 'Y' AND R.ROLE_ID IN #{role})
